// Redondea un importe a dos decimales para guardarlo en base de datos.
// El EPSILON evita que casos como 1.005 caigan al centimo de abajo por
// como se representan los decimales en coma flotante.
const round2 = (value: number): number =>
  Math.round(((Number(value) || 0) + Number.EPSILON) * 100) / 100;

// Formatea cualquier importe con dos decimales fijos. Antes se mostraba
// un solo decimal y los enteros sin decimales, pero eso perdia centimos:
// una base imponible de 65.04 salia como 65.0 y el VAT declarado dejaba
// de dar el 23% exacto. Todos los importes de la app comparten ahora la
// misma precision que los documentos fiscales.
const fmt2 = (value: number | string | null | undefined): string => {
  const num = typeof value === 'number' ? value : parseFloat(String(value ?? ''));
  if (!Number.isFinite(num)) return String(value ?? '');
  return round2(num).toFixed(2);
};

// Lee el valor de un <input type="number"> sin romper lo que el usuario esta escribiendo.
// Mientras el texto es intermedio ("1500." o "1500,") el navegador devuelve '' en
// e.target.value, asi que hacer Number(e.target.value) ahi mismo ponia 0 (o vaciaba el
// campo) y borraba lo tecleado. En ese caso devolvemos undefined para ignorar el evento
// y dejar que el usuario termine de escribir el decimal.
// Solo sirve para campos enteros (cantidades, cuotas, kilometraje); para importes con
// decimales hay que usar <NumberField>, ver el comentario de abajo.
//   number -> valor valido | null -> campo vacio | undefined -> ignorar
const readNumberInput = (e: { target: HTMLInputElement }): number | null | undefined => {
  if (e.target.validity.badInput) return undefined;
  if (e.target.value === '') return null;
  const num = Number(e.target.value);
  return Number.isFinite(num) ? num : undefined;
};

const toNumberOrNull = (value: number | string | null | undefined): number | null => {
  if (value === null || value === undefined || value === '') return null;
  const num = Number(value);
  return Number.isFinite(num) ? num : null;
};

// Campo para importes. Guarda el TEXTO que el usuario escribe, no el numero.
//
// Con <input type="number"> no alcanza con ignorar el evento intermedio: React restaura
// el valor del DOM a partir del estado cuando el onChange no lo cambia, asi que el punto
// recien tecleado desaparecia igual. Aca el input es de texto y su contenido es el estado
// local, de modo que "1250." se queda en pantalla; hacia afuera solo emitimos el numero
// cuando el texto es interpretable. inputMode="decimal" mantiene el teclado numerico en movil.
type NumberFieldProps = Omit<InputHTMLAttributes<HTMLInputElement>, 'value' | 'onChange' | 'type'> & {
  value: number | string | null | undefined;
  onValueChange: (value: number | null) => void;
};

const NumberField = ({ value, onValueChange, ...rest }: NumberFieldProps) => {
  const [text, setText] = useState(() => {
    const num = toNumberOrNull(value);
    return num === null ? '' : String(num);
  });
  // Ultimo valor emitido hacia el padre: distingue un cambio propio (no hay que tocar el
  // texto que se esta escribiendo) de uno que llega de afuera (hay que reflejarlo).
  const emitted = useRef<number | null>(toNumberOrNull(value));

  useEffect(() => {
    const incoming = toNumberOrNull(value);
    if (incoming !== emitted.current) {
      emitted.current = incoming;
      setText(incoming === null ? '' : String(incoming));
    }
  }, [value]);

  return (
    <input
      {...rest}
      type="text"
      inputMode="decimal"
      value={text}
      onChange={e => {
        const raw = e.target.value.replace(',', '.');
        if (raw !== '' && !/^-?\d*\.?\d*$/.test(raw)) return; // descarta letras y simbolos
        setText(raw);
        const parsed = raw === '' ? null : Number(raw);
        if (parsed !== null && !Number.isFinite(parsed)) return; // "-" o "." sueltos: sigue escribiendo
        emitted.current = parsed;
        onValueChange(parsed);
      }}
    />
  );
};

const parseMixtoAmounts = (notes: string | null | undefined, totalAmount: number): { cash: number; transfer: number } => {
  if (!notes) return { cash: totalAmount, transfer: 0 };
  const match = notes.match(/\[Pago Mixto\] Efectivo:\s*€?([0-9.]+)\s*\|\s*Transferencia:\s*€?([0-9.]+)/i);
  if (match) {
    const cash = parseFloat(match[1]) || 0;
    const transfer = parseFloat(match[2]) || 0;
    return { cash, transfer };
  }
  return { cash: totalAmount, transfer: 0 };
};

const getNextCustomerCode = (customers: Customer[]): string => {
  let maxNum = 1000;
  customers.forEach(c => {
    if (c.customer_code) {
      const match = c.customer_code.match(/\d+/);
      if (match) {
        const num = parseInt(match[0], 10);
        if (num > maxNum) {
          maxNum = num;
        }
      }
    }
  });
  return `US-${maxNum + 1}`;
};

const deduplicateCustomerCodes = async (existingCusts: Customer[], setCustomersState: (c: Customer[]) => void) => {
  const seenCodes = new Set<string>();
  const duplicates: Customer[] = [];
  
  existingCusts.forEach(c => {
    if (c.customer_code) {
      const code = c.customer_code.trim();
      if (seenCodes.has(code)) {
        duplicates.push(c);
      } else {
        seenCodes.add(code);
      }
    } else {
      duplicates.push(c);
    }
  });

  if (duplicates.length === 0) return;

  console.log(`[FastSheep] Found ${duplicates.length} customers with duplicate or missing codes. Automatically resolving...`);

  let maxNum = 1000;
  existingCusts.forEach(c => {
    if (c.customer_code) {
      const match = c.customer_code.match(/\d+/);
      if (match) {
        const num = parseInt(match[0], 10);
        if (num > maxNum) maxNum = num;
      }
    }
  });

  const updatedCusts = [...existingCusts];
  for (const c of duplicates) {
    maxNum++;
    const newCode = `US-${maxNum}`;
    const idx = updatedCusts.findIndex(x => x.id === c.id);
    if (idx !== -1) {
      updatedCusts[idx] = { ...updatedCusts[idx], customer_code: newCode };
      try {
        await upsertCustomer(updatedCusts[idx]);
      } catch (err) {
        console.error(`Error updating customer ${c.id} code:`, err);
      }
    }
  }
  setCustomersState(updatedCusts);
};

const convertHeicToJpgIfNeeded = async (file: File): Promise<File> => {
  let activeBlob: Blob = file;
  
  // 1. Convert HEIC to JPEG if needed
  const lowercaseName = file.name.toLowerCase();
  const isHeic = lowercaseName.endsWith('.heic') || lowercaseName.endsWith('.heif') || file.type === 'image/heic' || file.type === 'image/heif';
  
  if (isHeic) {
    try {
      const converted = await heic2any({
        blob: file,
        toType: 'image/jpeg',
        quality: 0.8
      });
      activeBlob = Array.isArray(converted) ? converted[0] : converted;
    } catch (err) {
      console.error('Error converting HEIC image:', err);
    }
  }

  // 2. Load the image and resize to max 1080px on canvas (also handles regular images to compress/resize!)
  // If it's not an image file (e.g. PDF/document), just return the original file.
  const isImage = file.type.startsWith('image/') || isHeic;
  if (!isImage) {
    return file;
  }

  return new Promise(async (resolve) => {
    try {
      // Try memory-efficient native bitmap decoding first
      if (typeof window.createImageBitmap === 'function') {
        let bitmap = await createImageBitmap(activeBlob);
        let width = bitmap.width;
        let height = bitmap.height;
        const maxDimension = 1080;
        
        if (width > maxDimension || height > maxDimension) {
          if (width > height) {
            height = Math.round((height * maxDimension) / width);
            width = maxDimension;
          } else {
            width = Math.round((width * maxDimension) / height);
            height = maxDimension;
          }
          // Re-decode scaled down to save memory before canvas drawing
          bitmap.close();
          bitmap = await createImageBitmap(activeBlob, { resizeWidth: width, resizeHeight: height });
        }
        
        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(bitmap, 0, 0, width, height);
          bitmap.close();
          canvas.toBlob(
            (blob) => {
              if (blob) {
                const newName = file.name.replace(/\.[^/.]+$/, ".jpg");
                resolve(new File([blob], newName, { type: 'image/jpeg' }));
              } else {
                resolve(file);
              }
            },
            'image/jpeg',
            0.85
          );
          return;
        }
      }
    } catch (e) {
      console.warn('createImageBitmap failed, falling back to Image', e);
    }

    // Fallback to Image() for older browsers
    const img = new Image();
    img.src = URL.createObjectURL(activeBlob);
    
    img.onload = () => {
      URL.revokeObjectURL(img.src);
      
      let width = img.width;
      let height = img.height;
      const maxDimension = 1080;
      
      if (width > maxDimension || height > maxDimension) {
        if (width > height) {
          height = Math.round((height * maxDimension) / width);
          width = maxDimension;
        } else {
          width = Math.round((width * maxDimension) / height);
          height = maxDimension;
        }
      }
      
      const canvas = document.createElement('canvas');
      canvas.width = width;
      canvas.height = height;
      
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(img, 0, 0, width, height);
        canvas.toBlob(
          (blob) => {
            if (blob) {
              const newName = file.name.replace(/\.[^/.]+$/, ".jpg");
              resolve(new File([blob], newName, { type: 'image/jpeg' }));
            } else {
              resolve(file);
            }
          },
          'image/jpeg',
          0.85
        );
      } else {
        resolve(file);
      }
    };
    
    img.onerror = (err) => {
      console.error('Error loading image for resizing:', err);
      resolve(file);
    };
  });
};

const convertHeicToJpgList = async (files: FileList | File[] | null | undefined): Promise<File[]> => {
  if (!files) return [];
  const list = Array.from(files);
  const result: File[] = [];
  for (const f of list) {
    result.push(await convertHeicToJpgIfNeeded(f));
  }
  return result;
};

// ----------------------------------------------------
// TOAST SYSTEM
// ----------------------------------------------------
interface Toast { id: string; message: string; type: 'success' | 'error'; }

interface NoteEntry {
  id: string;
  date: string;
  content: string;
}

function parseLeadNotes(notesRaw: string | null | undefined): NoteEntry[] {
  if (!notesRaw || !notesRaw.trim()) return [];
  // 1. Try JSON array (new format)
  try {
    const parsed = JSON.parse(notesRaw);
    if (Array.isArray(parsed)) return parsed as NoteEntry[];
  } catch (e) {
    // not JSON
  }
  // 2. Try legacy format: [ISO_DATE] content\n---\n...
  if (notesRaw.includes('\n---\n') || /^\[20\d{2}-/.test(notesRaw)) {
    const segments = notesRaw.split('\n---\n').filter(s => s.trim());
    const entries: NoteEntry[] = segments.map(seg => {
      const match = seg.match(/^\[([^\]]+)\]\s*([\s\S]*)$/);
      if (match) {
        return { id: crypto.randomUUID(), date: match[1], content: match[2].trim() };
      }
      return { id: crypto.randomUUID(), date: new Date().toISOString(), content: seg.trim() };
    });
    if (entries.length > 0) return entries;
  }
  // 3. Fallback: single plain-text note
  return [{ id: 'init', date: new Date().toISOString(), content: notesRaw }];
}

function parseContractUrls(url: string | null | undefined): string[] {
  if (!url || !url.trim()) return [];
  if (url.startsWith('[') && url.endsWith(']')) {
    try {
      return JSON.parse(url);
    } catch {
      return [url];
    }
  }
  return [url];
}

function parseQuickReplyLang(title: string): { lang: 'es' | 'en' | 'pt'; cleanTitle: string } {
  const match = title.match(/^\[(es|en|pt)\]\s*(.*)$/i);
  if (match) {
    return {
      lang: match[1].toLowerCase() as 'es' | 'en' | 'pt',
      cleanTitle: match[2]
    };
  }
  return { lang: 'es', cleanTitle: title };
}

function isWithinLast30Days(dateStr: string | null | undefined): boolean {
  if (!dateStr) return false;
  const date = new Date(dateStr);
  if (isNaN(date.getTime())) return false;
  const now = new Date();
  const diffTime = now.getTime() - date.getTime();
  const diffDays = diffTime / (1000 * 60 * 60 * 24);
  return diffDays >= 0 && diffDays <= 30;
}

// Helper to send emails securely via Supabase Edge Function
// Destinatario por defecto de las alarmas de stock. Se guarda en cada
// alarma y se puede cambiar en el modal, para no tener que tocar codigo
// si manaña avisa otra persona.
const ALARM_DEFAULT_EMAIL = 'emilianoaguilera1990@outlook.com';

async function executeEmailSend(to: string, subject: string, html: string) {
  if (!to || !to.trim()) {
    console.warn('[EMAIL] Cannot send email: recipient address is empty.');
    return;
  }
  console.log(`[EMAIL] Attempting to send email to: ${to} with subject: "${subject}"`);
  try {
    const { data, error } = await supabase.functions.invoke('send-email', {
      body: { to, subject, html },
    });
    if (error) throw error;
    console.log(`[EMAIL SUCCESS] Email sent successfully to ${to}. Response:`, data);
  } catch (err: any) {
    console.error(`[EMAIL ERROR] Failed to send email to ${to}:`, err.message || err);
  }
}

// Aviso de stock bajo. Va en ingles como el resto de los correos que
// salen del sistema, y lleva el umbral ademas de la cantidad: sin el, el
// que lo recibe no sabe si 3 unidades es un problema o lo normal.
async function sendStockAlarmEmail(
  alarm: { product_key: string; label: string; threshold: number; notify_email: string },
  productName: string,
  qty: number,
) {
  const destino = (alarm.notify_email || '').trim() || ALARM_DEFAULT_EMAIL;
  const etiqueta = alarm.label ? ` (${alarm.label})` : '';
  const agotado = qty === 0;
  const subject = agotado
    ? `Out of stock: ${productName}`
    : `Low stock: ${productName} — ${qty} left`;

  const html = `
    <div style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif;
                font-size:15px;line-height:1.6;color:#1a1a1a;max-width:560px">
      <p style="font-size:22px;margin:0 0 4px">${agotado ? '🚨' : '⚠️'}</p>
      <h2 style="margin:0 0 12px;font-size:18px">
        ${agotado ? 'Out of stock' : 'Stock below threshold'}${etiqueta}
      </h2>
      <p><strong>${productName}</strong> has reached the level you configured.</p>
      <table style="width:100%;font-size:14px;border-collapse:collapse;margin:14px 0;">
        <tr>
          <td style="padding:6px 0;color:#6b7280;">Item code</td>
          <td style="padding:6px 0;text-align:right;font-weight:600;font-family:monospace;">${alarm.product_key}</td>
        </tr>
        <tr>
          <td style="padding:6px 0;color:#6b7280;">Units left</td>
          <td style="padding:6px 0;text-align:right;font-weight:700;color:${agotado ? '#dc2626' : '#b45309'};">${qty}</td>
        </tr>
        <tr>
          <td style="padding:6px 0;color:#6b7280;">Alarm threshold</td>
          <td style="padding:6px 0;text-align:right;font-weight:600;">${alarm.threshold}</td>
        </tr>
      </table>
      <p style="color:#555">${agotado
        ? 'There are no units left in stock.'
        : 'Time to reorder before it runs out.'}</p>
      <p style="margin-top:28px;padding-top:14px;border-top:1px solid #e4e4e4;font-size:12px;color:#777">
        The Fast Sheep — automatic stock alarm
      </p>
    </div>`;

  await executeEmailSend(destino, subject, html);
}

