    setAccFormStatus(acc?.status ?? 'Activa'); setSelectedAccountId(acc?.id ?? null);
    setAccFormRiderReadOnly(readOnlyRider);
    setAccFormForceLinkRiderMode(forceLinkRiderActive);
    setAccFormStartDate(acc?.start_date ?? new Date().toISOString().split('T')[0]);
    
    // Load existing customer data if linked
    const renterId = acc?.current_renter_id ?? null;
