  const handleDeleteBikePhoto = async (cust: Customer, indexToDelete: number) => {
    const custRentals = rentals.filter(r => r.customer_id === cust.id);
    const lastRental = custRentals.length > 0 ? [...custRentals].sort((a, b) => b.created_at.localeCompare(a.created_at))[0] : null;

    if (!lastRental) return;

    const confirmMsg = language === 'es' 
      ? '¿Estás seguro de que deseas eliminar esta foto de estado?' 
      : 'Are you sure you want to delete this condition photo?';
    
    if (!await asyncConfirm(confirmMsg)) return;

    try {
      setIsUploadingDoc('bike_photo');
      const currentPhotos = lastRental.condition_photos || [];
      const updatedPhotos = currentPhotos.filter((_, idx) => idx !== indexToDelete);
      
      const updatedRental = { ...lastRental, condition_photos: updatedPhotos };
      await upsertRental(updatedRental);
      triggerReload();
      showToast(language === 'es' ? 'Foto de la bicicleta eliminada.' : 'Bike photo deleted.', 'success');
    } catch (err) {
      console.error('Error deleting bike photo:', err);
      showToast(language === 'es' ? 'Error al eliminar la foto.' : 'Error deleting photo.', 'error');
    } finally {
      setIsUploadingDoc(null);
    }
  };

  const handleUploadInstagramPhoto = async (cust: Customer, file: File) => {
    const custRentals = rentals.filter(r => r.customer_id === cust.id);
    const lastRental = custRentals.length > 0 ? [...custRentals].sort((a, b) => b.created_at.localeCompare(a.created_at))[0] : null;

    if (!lastRental) {
      showToast(language === 'es' ? 'No hay un alquiler registrado para este rider.' : 'No rental registered for this rider.', 'error');
      return;
    }
    try {
      setIsUploadingDoc('instagram_photo');
      showToast(language === 'es' ? 'Subiendo foto para Instagram...' : 'Uploading Instagram photo...');
      const photoUrl = await uploadRentalPhoto(lastRental.id, file);
      
      const currentPhotos = lastRental.instagram_photos || [];
      const updatedPhotos = [...currentPhotos, photoUrl];
      
      const updatedRental = { ...lastRental, instagram_photos: updatedPhotos };
      await upsertRental(updatedRental);
      triggerReload();
      showToast(language === 'es' ? 'Foto de Instagram agregada exitosamente.' : 'Instagram photo added successfully.', 'success');
    } catch (err) {
      console.error('Error uploading Instagram photo:', err);
      showToast(language === 'es' ? 'Error al subir la foto.' : 'Error uploading photo.', 'error');
    } finally {
      setIsUploadingDoc(null);
    }
  };

  const handleDeleteInstagramPhoto = async (cust: Customer, indexToDelete: number) => {
    const custRentals = rentals.filter(r => r.customer_id === cust.id);
    const lastRental = custRentals.length > 0 ? [...custRentals].sort((a, b) => b.created_at.localeCompare(a.created_at))[0] : null;

    if (!lastRental) return;

    const confirmMsg = language === 'es' 
      ? '¿Estás seguro de que deseas eliminar esta foto de Instagram?' 
      : 'Are you sure you want to delete this Instagram photo?';
    
    if (!await asyncConfirm(confirmMsg)) return;

    try {
      setIsUploadingDoc('instagram_photo');
      const currentPhotos = lastRental.instagram_photos || [];
      const updatedPhotos = currentPhotos.filter((_, idx) => idx !== indexToDelete);
      
      const updatedRental = { ...lastRental, instagram_photos: updatedPhotos };
      await upsertRental(updatedRental);
      triggerReload();
      showToast(language === 'es' ? 'Foto de Instagram eliminada.' : 'Instagram photo deleted.', 'success');
    } catch (err) {
      console.error('Error deleting Instagram photo:', err);
      showToast(language === 'es' ? 'Error al eliminar la foto.' : 'Error deleting photo.', 'error');
    } finally {
      setIsUploadingDoc(null);
    }
  };

    const handleOpenWhatsappModal = (phone: string, name: string) => {
    const cleanPhone = phone.replace(/\D/g, '');
    const template = localStorage.getItem('default_wa_template') || 
      (language === 'es' 
        ? 'Hola {nombre}, te contacto de The Fast Sheep 🚴' 
        : 'Hi {nombre}, reaching out from The Fast Sheep 🚴');
    
    const filledMessage = template
      .replace(/{nombre}/gi, name)
      .replace(/{name}/gi, name);
      
    setWhatsappPhone(cleanPhone);
    setWhatsappName(name);
    setWhatsappMessageText(filledMessage);
    setWhatsappModalOpen(true);
  };

  const handleSaveWhatsappTemplate = () => {
    let templateText = whatsappMessageText;
    if (whatsappName) {
      const escapedName = whatsappName.replace(/[-/\\^$*+?.()|[\]{}]/g, '\\$&');
      const regex = new RegExp(escapedName, 'gi');
      templateText = templateText.replace(regex, '{nombre}');
    }
    localStorage.setItem('default_wa_template', templateText);
    showToast(
      language === 'es' 
        ? '💬 ¡Plantilla predeterminada guardada!' 
        : '💬 Default template saved!', 
      'success'
    );
  };

  const startEditingRider = (cust: Customer) => {
    setEditFirstName(cust.first_name);
    setEditLastName(cust.last_name);
    setEditCustomerCode(cust.customer_code ? cust.customer_code.replace(/^US-?/i, '') : '');
    setEditNationality(cust.nationality || '');
    setEditEmail(cust.email || '');
    setEditPhone(cust.phone || '');
    setEditReferral(cust.referral_source || '');
    setIsEditingRider(true);
  };

  const handleSaveRiderEdits = async (cust: Customer) => {
    if (!editFirstName.trim() || !editLastName.trim()) {
      showToast(language === 'es' ? 'Nombre y apellido son requeridos.' : 'First and last name are required.', 'error');
      return;
    }
    try {
      const updatedRider: Customer = {
        ...cust,
        first_name: editFirstName.trim(),
        last_name: editLastName.trim(),
        customer_code: 'US-' + editCustomerCode.trim().replace(/^US-?/i, ''),
        nationality: editNationality.trim(),
        email: editEmail.trim(),
        phone: editPhone.trim(),
        referral_source: editReferral.trim(),
      };
      await upsertCustomer(updatedRider);
      setIsEditingRider(false);
      triggerReload();
      showToast(language === 'es' ? 'Datos del rider actualizados.' : 'Rider details updated.', 'success');
    } catch (err) {
      showToast(language === 'es' ? 'Error al actualizar los datos.' : 'Error updating details.', 'error');
    }
  };



  const handleWizBikeChange = (id: string) => {
    setWizBikeId(id);
    const bike = products.find(p => p.id === id);
    if (bike) { 
      setWizRate(bike.suggested_weekly_rate ?? 60); 
      setWizDeposit(bike.suggested_deposit ?? 150); 
      setWizOdometer(bike.odometer ?? '');
    }
    const linkedLock = products.find(p => p.category_id === catLockId && p.custom_field_values?.associated_bike_id === id);
    if (linkedLock) {
      setWizLockId(linkedLock.id);
    } else {
      setWizLockId('');
    }
  };

  const handleWizBatteryChange = (id: string) => {
    setWizBatteryIds(prev =>
      prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]
    );
  };

  // Sustituye la bici de un alquiler vivo. El alquiler es el mismo (rider,
  // contrato y pagos siguen), solo cambia la unidad: por eso se cierra el tramo
  // de asignacion anterior y se abre uno nuevo, en vez de tocar el historial.
  const handleConfirmBikeSwap = async (rental: Rental) => {
    if (!swapNewBikeId) return;
    setSwapSubmitting(true);
    try {
      const oldBike = products.find(p => p.id === rental.bike_id);
      const newBike = products.find(p => p.id === swapNewBikeId);
      if (!newBike) throw new Error('bici destino no encontrada');

      // 1. Historial de asignacion: cierra el tramo vivo y abre el nuevo.
      await switchRentalBike(rental.id, swapNewBikeId, swapEffectiveDate);

      // 2. El alquiler pasa a apuntar a la bici nueva, con las condiciones nuevas.
      await upsertRental({
        ...rental,
        bike_id: swapNewBikeId,
        rental_rate: swapRate,
        deposit_amount: swapDeposit,
      });

      // 3. Estados de stock de las dos bicis.
      const updates: Promise<void>[] = [];
      if (oldBike) {
        // "A taller" la saca del pool de disponibles y la deja marcada para revisar.
        updates.push(upsertProduct(swapOldBikeStatus === 'Requiere Service'
          ? { ...oldBike, status: 'Mantenimiento', maintenance_status: 'Requiere Service' }
          : { ...oldBike, status: 'Disponible' }));
      }
      updates.push(upsertProduct({ ...newBike, status: 'Rentada' }));

      // 4. Baterias: liberar las que salen, ocupar las que entran.
      const prevBatteryIds = rentalItems
        .filter(i => i.rental_id === rental.id && i.item_type === 'battery')
        .map(i => i.product_id);
      prevBatteryIds.filter(id => !swapBatteryIds.includes(id)).forEach(id => {
        const p = products.find(x => x.id === id);
        if (p) updates.push(upsertProduct({ ...p, status: 'Disponible' }));
      });
      swapBatteryIds.filter(id => !prevBatteryIds.includes(id)).forEach(id => {
        const p = products.find(x => x.id === id);
        if (p) updates.push(upsertProduct({ ...p, status: 'Rentada' }));
      });

      // 5. Candado: o se revincula a la bici nueva, o se cambia por otro.
      const prevLock = rentalItems
        .filter(i => i.rental_id === rental.id && i.item_type === 'kit_accessory')
        .map(i => products.find(p => p.id === i.product_id))
        .find(p => p && p.category_id === catLockId) || null;
      let finalLockId = '';
      if (swapKeepLock && prevLock) {
        finalLockId = prevLock.id;
        updates.push(upsertProduct({
          ...prevLock,
          status: 'Rentada',
          custom_field_values: { ...prevLock.custom_field_values, associated_bike_id: swapNewBikeId },
        }));
      } else {
        if (prevLock) {
          updates.push(upsertProduct({
            ...prevLock,
            status: 'Disponible',
            custom_field_values: { ...prevLock.custom_field_values, associated_bike_id: null },
          }));
        }
        if (swapNewLockId) {
          const nl = products.find(p => p.id === swapNewLockId);
          if (nl) {
            finalLockId = nl.id;
            updates.push(upsertProduct({
              ...nl,
              status: 'Rentada',
              custom_field_values: { ...nl.custom_field_values, associated_bike_id: swapNewBikeId },
            }));
          }
        }
      }
      await Promise.all(updates);

      // 6. Rehacer los items del alquiler (baterias + candado + resto del kit).
      const otherKitIds = rentalItems
        .filter(i => i.rental_id === rental.id && i.item_type === 'kit_accessory')
        .map(i => i.product_id)
        .filter(id => {
          const p = products.find(x => x.id === id);
          return p && p.category_id !== catLockId;
        });
      await deleteRentalItems(rental.id);
      const items: RentalItem[] = [
        ...swapBatteryIds.map(id => ({ id: crypto.randomUUID(), rental_id: rental.id, product_id: id, item_type: 'battery' as const })),
        ...(finalLockId ? [{ id: crypto.randomUUID(), rental_id: rental.id, product_id: finalLockId, item_type: 'kit_accessory' as const }] : []),
        ...otherKitIds.map(id => ({ id: crypto.randomUUID(), rental_id: rental.id, product_id: id, item_type: 'kit_accessory' as const })),
      ];
      if (items.length) await insertRentalItems(items);

      // 7. Anexo al contrato. Solo lista lo que efectivamente cambia: si las
      // baterias siguen siendo las mismas, ni se mencionan.
      const changes: AmendmentChange[] = [];
      const serialOf = (p?: Product) => `${p?.frame_serial || '—'} (${p?.serial_number || '—'})`;
      // El modelo solo se lista si de verdad cambia: sustituir una unidad por
      // otra del mismo modelo no es un cambio de condiciones.
      if ((oldBike?.name ?? '') !== newBike.name) {
        changes.push({ label: 'Brand and Model', before: oldBike?.name ?? '—', after: newBike.name });
      }
      changes.push({ label: 'Serial Number', before: serialOf(oldBike), after: serialOf(newBike) });
      const sameBatteries =
        prevBatteryIds.length === swapBatteryIds.length &&
        prevBatteryIds.every(id => swapBatteryIds.includes(id));
      if (!sameBatteries) {
        const listOf = (ids: string[]) => ids.length
          ? ids.map(id => { const p = products.find(x => x.id === id); return `${p?.battery_serial || '—'} (${p?.serial_number || '—'})`; }).join(', ')
          : '—';
        changes.push({ label: 'Batteries', before: listOf(prevBatteryIds), after: listOf(swapBatteryIds) });
      }
      if (swapRate !== rental.rental_rate) {
        changes.push({ label: contractRatePeriodLabel(rental.rate_type), before: `€${fmt2(rental.rental_rate)}`, after: `€${fmt2(swapRate)}` });
      }
      if (swapDeposit !== rental.deposit_amount) {
        changes.push({ label: 'Security Deposit', before: `€${fmt2(rental.deposit_amount)}`, after: `€${fmt2(swapDeposit)}` });
      }

      let avisoAnexo = '';
      const cust = customers.find(c => c.id === rental.customer_id);
      const priorSnapshot = rental.contract_snapshot;
      const snapshotAfter: RentalContractSnapshot | null = priorSnapshot ? {
        ...priorSnapshot,
        bike_brand_model: newBike.name,
        bike_serial: newBike.frame_serial ?? '',
        bike_ref: newBike.serial_number ?? '',
        rate_amount: swapRate,
        deposit_amount: swapDeposit,
        battery_count: swapBatteryIds.length,
      } : null;

      try {
        const number = await nextAmendmentNumber(rental.id);
        const amendment = await createContractAmendment({
          rental_id: rental.id,
          number,
          effective_date: swapEffectiveDate,
          changes,
          snapshot_after: snapshotAfter,
          note: null,
          customer_name: cust ? `${cust.first_name} ${cust.last_name}`.trim() : '',
          customer_email: cust?.email ?? '',
          email_lang: priorSnapshot?.email_lang ?? 'en',
        });
        const url = `${window.location.origin}${window.location.pathname}?anexo=${amendment.id}`;
        if (amendment.customer_email) sendAmendmentInviteEmail(amendment, url);
        try { await navigator.clipboard.writeText(url); } catch { /* ignore */ }
        avisoAnexo = language === 'es' ? ` · 📄 Anexo Nº ${number} enviado` : ` · 📄 Amendment No. ${number} sent`;
      } catch (err) {
        console.error('No se pudo crear el anexo:', err);
        avisoAnexo = language === 'es' ? ' · ⚠️ no se pudo emitir el anexo' : ' · ⚠️ amendment could not be issued';
      }

      // 8. Checklist de entrega de la unidad nueva: deja constancia firmada del
      // estado en que se entrega, igual que en el alta.
      let avisoChecklist = '';
      if (cust?.email) {
        try {
          const checklist = await createDeliveryChecklist({
            rental_id: rental.id,
            audience: 'customer',
            customer_name: cust ? `${cust.first_name} ${cust.last_name}`.trim() : '',
            customer_email: cust.email,
            email_lang: priorSnapshot?.email_lang ?? 'en',
            bike_model: newBike.name,
            bike_serial: newBike.frame_serial ?? '',
            bike_ref: newBike.serial_number ?? '',
            delivery_date: swapEffectiveDate,
          });
          const clUrl = `${window.location.origin}${window.location.pathname}?checklist=${checklist.id}`;
          sendDeliveryChecklistInviteEmail(checklist, clUrl, priorSnapshot?.email_lang ?? 'en');
          avisoChecklist = language === 'es' ? ' · 📋 checklist enviada' : ' · 📋 checklist sent';
        } catch (err) {
          console.error('No se pudo emitir la checklist del cambio:', err);
          avisoChecklist = language === 'es' ? ' · ⚠️ sin checklist' : ' · ⚠️ no checklist';
        }
      }

      setSwapModalRentalId(null);
      triggerReload();
      // Un solo aviso: dos toasts en el mismo milisegundo comparten clave en React.
      showToast(
        (language === 'es'
          ? `🔄 Cambio aplicado: ${oldBike?.serial_number ?? '—'} → ${newBike.serial_number}`
          : `🔄 Swap applied: ${oldBike?.serial_number ?? '—'} → ${newBike.serial_number}`) + avisoAnexo + avisoChecklist,
        'success'
      );
    } catch (err) {
      console.error('Bike swap failed:', err);
      showToast(language === 'es' ? 'No se pudo aplicar el cambio de bici.' : 'Could not apply the bike swap.', 'error');
    }
    setSwapSubmitting(false);
  };

  const handleConfirmRental = async () => {
    if (!wizBikeId || !wizFirstName || !wizLastName) {
      showToast('Falta información requerida (Bike, Nombre).', 'error'); return;
    }
    try {
      setWizUploadingEvidence(true);

      // Find or create customer
      let rider = customers.find(c => c.email.toLowerCase() === wizEmail.toLowerCase());
      const customerId = rider?.id ?? crypto.randomUUID();
      if (!rider) {
        let finalCode = '';
        const suffix = wizCustomerCode.trim().replace(/^US-?/i, '');
        if (suffix) {
          finalCode = 'US-' + suffix;
        } else {
          finalCode = getNextCustomerCode(customers);
        }
        rider = {
          id: customerId, customer_code: finalCode,
          first_name: wizFirstName, last_name: wizLastName, email: wizEmail,
          phone: wizPhone, address: wizAddress, id_document_url: '',
          referral_source: wizReferral, nationality: wizNationality, notes: '', created_at: new Date().toISOString(),
        };
        await upsertCustomer(rider);
      } else if (wizAddress.trim() && wizAddress.trim() !== (rider.address ?? '').trim()) {
        // Existing rider: keep the address up to date, it is printed on the contract.
        rider = { ...rider, address: wizAddress.trim() };
        await upsertCustomer(rider);
      }

      // Upload rider ID document if provided
      if (wizIdDocFile) {
        try {
          const idUrl = await uploadRiderDocument(customerId, wizIdDocFile);
          rider = { ...rider, id_document_url: idUrl };
          await upsertCustomer(rider);
        } catch (uploadErr) {
          console.warn('Failed to upload rider document:', uploadErr);
        }
      }

      const bikeProduct = products.find(p => p.id === wizBikeId);
      const newRentId = crypto.randomUUID();

      // Upload condition photos
      let conditionPhotoUrls: string[] = [];
      if (wizConditionFiles.length > 0) {
        try {
          const uploadPromises = wizConditionFiles.map(file => uploadRentalPhoto(newRentId, file));
          conditionPhotoUrls = await Promise.all(uploadPromises);
        } catch (uploadErr) {
          console.warn('Failed to upload condition photos:', uploadErr);
        }
      }

      // Upload Instagram photos
      let instagramPhotoUrls: string[] = [];
      if (wizInstagramFiles.length > 0) {
        try {
          const uploadPromises = wizInstagramFiles.map(file => uploadRentalPhoto(newRentId, file));
          instagramPhotoUrls = await Promise.all(uploadPromises);
          console.log('Successfully uploaded Instagram photos to Supabase Storage:', instagramPhotoUrls);
        } catch (uploadErr) {
          console.warn('Failed to upload Instagram photos:', uploadErr);
        }
      }

      // Handle contract: upload physical contract photo or mark as digital
      let contractUrl: string | null = null;
      let contractType: 'photo' | 'digital' = 'digital';
      if (wizContractMode === 'physical' && wizPhysicalContractFiles.length > 0) {
        try {
          const uploadedUrls = await Promise.all(wizPhysicalContractFiles.map(f => uploadContractPhoto(newRentId, f)));
          contractUrl = JSON.stringify(uploadedUrls);
          contractType = 'photo';
        } catch (uploadErr) {
          console.warn('Failed to upload contract photo:', uploadErr);
        }
      } else {
        contractType = 'digital';
        contractUrl = null; // Will be filled when rider signs via the public link
      }

      const parsedStartParts = wizStartDate.split('-');
      const returnDateObj = new Date(parseInt(parsedStartParts[0]), parseInt(parsedStartParts[1]) - 1, parseInt(parsedStartParts[2]) + 21);
      const calculatedReturnDate = `${returnDateObj.getFullYear()}-${String(returnDateObj.getMonth() + 1).padStart(2, '0')}-${String(returnDateObj.getDate()).padStart(2, '0')}`;

      const newRental: Rental = {
        id: newRentId, bike_id: wizBikeId, customer_id: rider.id,
        has_insurance: wizHasInsurance, deposit_amount: wizDeposit,
        rental_rate: wizRate, rate_type: wizRateType,
        start_date: wizStartDate, end_date: null,
        scheduled_return_date: calculatedReturnDate,
        return_notice_date: null, odometer_start: typeof wizOdometer === 'number' ? wizOdometer : (bikeProduct?.odometer ?? 0), odometer_end: null,
        status: 'Activo', contract_type: contractType,
        contract_url: contractUrl,
        condition_photos: conditionPhotoUrls,
        instagram_photos: instagramPhotoUrls,
        has_kit: wizHasKit,
        kit_details: wizHasKit && wizKitProductIds.length > 0
          ? wizKitProductIds.map(id => { const p = products.find(pr => pr.id === id); return p ? `${p.serial_number} (${p.name})` : ''; }).filter(Boolean).join(', ')
          : wizKitDetails,
        deposit_refunded: null, damage_report: null, created_at: new Date().toISOString(),
        deposit_received_via: wizDepositPaymentMethod,
        // Facturacion automatica: los alquileres semanales entran al cron.
        // Sin next_invoice_date el cron los ignora, asi que se fija el
        // primer cobro una semana despues del inicio.
        auto_invoice: wizRateType === 'semanal',
        next_invoice_date: wizRateType === 'semanal'
          ? (() => {
              const [yy, mm, dd] = wizStartDate.split('-').map(Number);
              const d = new Date(yy, mm - 1, dd + 7);
              return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
            })()
          : null,
      };
      await upsertRental(newRental);

      // Documentos de alta: recibo del deposito (si hay) y factura de la
      // primera semana/periodo de alquiler (si hay importe). La bici se
      // entrega al cobrar, asi que ambas nacen ya pagadas. Van en el
      // MISMO email para no mandar dos correos por la misma alta. Un
      // fallo aqui no tumba la creacion del alquiler: se avisa aparte.
      const firstDocIds: string[] = [];
      if (wizDeposit > 0) {
        try {
          const dep = await issueDepositReceipt({
            rentalId: newRentId,
            amount: wizDeposit,
            paymentMethod: wizDepositPaymentMethod,
            paymentDate: wizStartDate,
          });
          firstDocIds.push(dep.id);
        } catch (depErr) {
          console.error('[FastSheep] no se pudo emitir el recibo de deposito:', depErr);
        }
      }
      if (wizRate > 0) {
        try {
          const firstInvoice = await issueRentalInvoice({
            rentalId: newRentId,
            amount: wizRate,
            paymentMethod: wizRatePaymentMethod,
            paymentDate: wizStartDate,
            description: language === 'es' ? 'Alquiler de e-bike' : 'E-bike rental',
          });
          firstDocIds.push(firstInvoice.id);
        } catch (invErr) {
          console.error('[FastSheep] no se pudo emitir la factura de la primera semana:', invErr);
        }
      }
      if (firstDocIds.length > 0) {
        try {
          await generateDocumentPdfBatch(firstDocIds, true);
        } catch (pdfErr) {
          console.error('[FastSheep] no se pudieron generar/enviar los documentos de alta:', pdfErr);
        }
      }

      // Primer tramo del historial de asignacion de bici.
      try {
        await openBikeAssignment(newRentId, wizBikeId, wizStartDate);
      } catch (err) {
        console.warn('No se pudo abrir el tramo de asignacion de bici:', err);
      }

      // Trigger Rental Confirmation Email
      if (rider) {
        sendRentalConfirmationEmail({
          ...newRental,
          monthly_rate: wizRateType === 'mensual' ? wizRate : Math.round(wizRate * 4), // Normalize to monthly rate description
        }, bikeProduct, rider, wizEmailLang, emailTemplates);

        // Schedule first monthly payment reminder in Supabase Calendar
        const startParts = wizStartDate.split('-');
        const firstInstallmentDate = new Date(parseInt(startParts[0]), parseInt(startParts[1]) - 1 + 1, parseInt(startParts[2]));
        const formattedFirstInstallmentDate = `${firstInstallmentDate.getFullYear()}-${String(firstInstallmentDate.getMonth() + 1).padStart(2, '0')}-${String(firstInstallmentDate.getDate()).padStart(2, '0')}`;

        const rentalReminderEvent = {
          id: crypto.randomUUID(),
          title: `🚲 Pago Alquiler: ${rider.first_name} ${rider.last_name}`,
          description: `Mensualidad del alquiler de la bicicleta: ${bikeProduct?.name || 'E-Bike'} (${bikeProduct?.serial_number || 'S/N'}). Monto: €${fmt2(wizRateType === 'mensual' ? wizRate : Math.round(wizRate * 4))}.`,
          event_date: formattedFirstInstallmentDate,
          remind_one_week: true,
          remind_one_day: true,
          status: 'Pendiente' as const
        };
        await upsertEvent(rentalReminderEvent);
      }

      // Update bike/battery/lock status
      const updates: Promise<void>[] = [];
      if (bikeProduct) updates.push(upsertProduct({ ...bikeProduct, status: 'Rentada', odometer: typeof wizOdometer === 'number' ? wizOdometer : bikeProduct.odometer }));
      wizBatteryIds.forEach(batId => {
        const battProduct = products.find(p => p.id === batId);
        if (battProduct) updates.push(upsertProduct({ ...battProduct, status: 'Rentada' }));
      });
      const lockProduct = products.find(p => p.id === wizLockId);
      if (lockProduct) {
        updates.push(upsertProduct({
          ...lockProduct,
          status: 'Rentada',
          custom_field_values: {
            ...lockProduct.custom_field_values,
            associated_bike_id: wizBikeId,
            keep_associated: wizKeepAssociated
          }
        }));
      }
      // Update kit product statuses (handle generic products by splitting 1 unit off)
      const resolvedKitIds: string[] = [];
      for (const kitId of wizKitProductIds) {
        const kitProduct = products.find(p => p.id === kitId);
        if (!kitProduct) continue;
        const dist = kitProduct.custom_field_values?.location_distribution as Record<string, number> | undefined;
        const totalQty = dist ? Object.values(dist).reduce((a, b) => a + b, 0) : 0;
        if (dist && totalQty > 1) {
          const splitId = crypto.randomUUID();
          // Use the location chosen by the operator in Step 3; fall back to the one with most stock.
          const autoLoc = Object.entries(dist).sort((a, b) => b[1] - a[1])[0]?.[0] || 'Almacén Central';
          const chosenLoc = (wizKitLocations[kitId] && (dist[wizKitLocations[kitId]] || 0) > 0) ? wizKitLocations[kitId] : autoLoc;
          updates.push(upsertProduct({
            ...kitProduct,
            id: splitId,
            status: 'Rentada',
            custom_field_values: { ...kitProduct.custom_field_values, location: chosenLoc, location_distribution: undefined },
          }));
          const updatedDist = { ...dist };
          const locToDecrement = (updatedDist[chosenLoc] || 0) > 0 ? chosenLoc : (Object.keys(updatedDist).find(k => updatedDist[k] > 0) || chosenLoc);
          updatedDist[locToDecrement] = (updatedDist[locToDecrement] || 1) - 1;
          Object.keys(updatedDist).forEach(k => { if (updatedDist[k] <= 0) delete updatedDist[k]; });
          const newTotal = Object.values(updatedDist).reduce((a, b) => a + b, 0);
          if (newTotal <= 0) {
            updates.push(upsertProduct({ ...kitProduct, status: 'Rentada', custom_field_values: { ...kitProduct.custom_field_values, location_distribution: undefined } }));
          } else {
            updates.push(upsertProduct({ ...kitProduct, custom_field_values: { ...kitProduct.custom_field_values, location_distribution: updatedDist } }));
          }
          resolvedKitIds.push(splitId);
        } else {
          updates.push(upsertProduct({ ...kitProduct, status: 'Rentada' }));
          resolvedKitIds.push(kitId);
        }
      }
      await Promise.all(updates);

      // Sub-items
      const subItems: RentalItem[] = [];
      wizBatteryIds.forEach(batId => {
        subItems.push({ id: crypto.randomUUID(), rental_id: newRentId, product_id: batId, item_type: 'battery' });
      });
      if (wizLockId)    subItems.push({ id: crypto.randomUUID(), rental_id: newRentId, product_id: wizLockId,    item_type: 'kit_accessory' });
      // Kit accessory items
      resolvedKitIds.forEach(kitId => {
        subItems.push({ id: crypto.randomUUID(), rental_id: newRentId, product_id: kitId, item_type: 'kit_accessory' });
      });
      if (subItems.length) await insertRentalItems(subItems);

      // Initial payment
      if (wizRate > 0) {
        await insertPayment({
          id: crypto.randomUUID(), rental_id: newRentId, amount: wizRate,
          payment_date: wizStartDate,
          payment_method: 'Renta',
          received_via: wizRatePaymentMethod,
        });
      }

      // Link Gig Account if selected
      if (wizGigAccountId) {
        const gigAcc = appAccounts.find(a => a.id === wizGigAccountId);
        if (gigAcc) {
          await upsertAppAccount({ 
            ...gigAcc, 
            current_renter_id: rider.id,
            start_date: wizStartDate
          });

          // Trigger App Account Assigned email
          const platformName = platforms.find(p => p.id === gigAcc.platform_id)?.name || 'Plataforma';
          sendAppAccountAssignedEmail(rider, platformName, gigAcc.username || gigAcc.platform_account_number || '', gigAcc.password || '—', gigAcc.bank_details || '—', wizEmailLang, emailTemplates);
        }
      }

      // Digital contract: freeze the rental details, then email the signing link.
      // The snapshot is what the rider reads and signs, so later rate changes
      // never alter the agreement that was accepted.
      if (wizContractMode === 'digital' && wizEmail) {
        const signUrl = `${window.location.origin}${window.location.pathname}?firmar=${newRentId}`;
        const snapshot: RentalContractSnapshot = {
          lessee_name: `${rider.first_name} ${rider.last_name}`.trim(),
          lessee_address: wizAddress.trim() || rider.address || '',
          lessee_phone: wizPhone || rider.phone || '',
          lessee_email: wizEmail,
          email_lang: wizEmailLang,
          bike_brand_model: bikeProduct?.name ?? '',
          bike_serial: bikeProduct?.frame_serial ?? '',
          bike_ref: bikeProduct?.serial_number ?? '',
          start_date: wizStartDate,
          payment_due_weekday: contractPaymentWeekday(wizStartDate),
          rate_amount: wizRate,
          rate_type: wizRateType,
          deposit_amount: wizDeposit,
          battery_count: wizBatteryIds.length,
        };
        try {
          await supabase.from('rentals').update({ contract_snapshot: snapshot }).eq('id', newRentId);
          sendRentalContractInviteEmail(snapshot, signUrl, wizEmailLang);
          showToast(`📄 ${language === 'es' ? 'Contrato enviado' : 'Contract sent'}: ${signUrl}`, 'success');
        } catch (err) {
          console.error('Failed to send rental contract:', err);
          showToast(language === 'es' ? 'No se pudo enviar el contrato.' : 'Could not send the contract.', 'error');
        }
        try { await navigator.clipboard.writeText(signUrl); } catch { /* ignore */ }
      }

      // Create & send the customer delivery checklist (link emailed to the rider)
      if (wizSendDeliveryChecklist && wizEmail) {
        try {
          const checklist = await createDeliveryChecklist({
            rental_id: newRentId,
            audience: 'customer',
            customer_name: `${rider.first_name} ${rider.last_name}`.trim(),
            customer_email: wizEmail,
            email_lang: wizEmailLang,
            bike_model: bikeProduct?.name ?? '',
            bike_serial: bikeProduct?.frame_serial ?? '',
            bike_ref: bikeProduct?.serial_number ?? '',
            delivery_date: new Date().toISOString().split('T')[0],
          });
          const checklistUrl = `${window.location.origin}${window.location.pathname}?checklist=${checklist.id}`;
          sendDeliveryChecklistInviteEmail(checklist, checklistUrl, wizEmailLang);
          showToast(`✅ ${language === 'es' ? 'Checklist enviada' : 'Checklist sent'}: ${checklistUrl}`, 'success');
          try { await navigator.clipboard.writeText(checklistUrl); } catch { /* ignore */ }
        } catch (err) {
          console.error('Failed to create/send delivery checklist:', err);
          showToast(language === 'es' ? 'No se pudo enviar la checklist de entrega.' : 'Could not send the delivery checklist.', 'error');
        }
      }

      // Create the internal technical inspection checklist (operator-filled).
      // Always created so it is available in the rider profile, even if completed later.
      try {
        await persistInternalChecklist({
          existingId: null,
          rentalId: newRentId,
          customerName: `${rider.first_name} ${rider.last_name}`.trim(),
          bikeModel: bikeProduct?.name ?? '',
          bikeSerial: bikeProduct?.frame_serial ?? '',
          bikeRef: bikeProduct?.serial_number ?? '',
          deliveryDate: new Date().toISOString().split('T')[0],
          value: wizInternalChecklist,
        });
      } catch (err) {
        console.error('Failed to create internal checklist:', err);
      }


      // Reset wizard
      setWizBikeId(''); setWizBatteryIds([]); setWizLockId(''); setWizGigAccountId(null);
      setWizFirstName(''); setWizLastName(''); setWizEmail('');
      setWizPhone(''); setWizAddress(''); setWizRiderEmail(''); setSignatureData(null);
      setWizKitProductIds([]); setWizKitLocations({}); setWizHasKit(true); setWizKitDetails('');
      setWizCustomerCode(''); setWizStartDate(new Date().toISOString().split('T')[0]);
      // Reset Step 7 evidence states
      setWizConditionFiles([]); setWizConditionPreviews([]);
      setWizInstagramFiles([]); setWizInstagramPreviews([]);
      setWizIdDocFile(null); setWizIdDocPreview('');
      setWizContractMode(null); setWizPhysicalContractFiles([]); setWizPhysicalContractPreviews([]);
      setWizUploadingEvidence(false);
      setWizSendDeliveryChecklist(true);
      setWizInternalChecklist(emptyInternalChecklist());
      setWizShowInternalChecklist(false);
      setWizardStep(1); triggerReload(); setCurrentTab('rental_wizard'); setShowRentalWizard(false);
      showToast('¡Alquiler registrado exitosamente!', 'success');
    } catch (err) {
      setWizUploadingEvidence(false);
      setWizSendDeliveryChecklist(true);
      setWizInternalChecklist(emptyInternalChecklist());
      setWizShowInternalChecklist(false);
      showToast('Error al registrar el alquiler. Intenta de nuevo.', 'error');
    }
  };

  // ----------------------------------------------------------
  // ROI BADGE HELPER
  // ----------------------------------------------------------
  const renderROIBadge = (productId: string) => {
    const stats = calculateProductROI(productId, products, categories, rentals, rentalItems, payments, expenses, records, bikeAssignments);
    const cls = stats.roi < 10 ? 'roi-red' : stats.roi < 50 ? 'roi-orange' : 'roi-green';
    return (
      <span 
        className={`roi-badge ${cls}`} 
        style={{ cursor: 'pointer' }}
        title={language === 'es' ? 'Ver detalle de ROI' : 'View ROI details'}
        onClick={(e) => {
          e.stopPropagation();
          setSelectedProductId(productId);
          setModalType('roiDetails');
        }}
      >
        {stats.roi}% ROI
      </span>
    );
  };

  // ----------------------------------------------------------
  // CALENDAR HELPERS
  // ----------------------------------------------------------
  const calFirstDay = new Date(calYear, calMonth, 1).getDay(); // 0=Sun
  const calOffset   = (calFirstDay + 6) % 7; // convert to Mon-start
  const calDays     = new Date(calYear, calMonth + 1, 0).getDate();
  const calMonthNames = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  const calMonthNamesEs = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];

  const prevCalMonth = () => { if (calMonth === 0) { setCalYear(y => y - 1); setCalMonth(11); } else setCalMonth(m => m - 1); };
  const nextCalMonth = () => { if (calMonth === 11) { setCalYear(y => y + 1); setCalMonth(0); }  else setCalMonth(m => m + 1); };

  const getDaysOfWeek = useCallback((d: Date) => {
    const current = new Date(d.getTime());
    const day = current.getDay();
    const diff = current.getDate() - day + (day === 0 ? -6 : 1);
    const monday = new Date(current.getTime());
    monday.setDate(diff);
    
    const days = [];
    for (let i = 0; i < 7; i++) {
      const dayDate = new Date(monday.getTime());
      dayDate.setDate(monday.getDate() + i);
      days.push(dayDate);
    }
    return days;
  }, []);

  const prevWeek = useCallback(() => {
    setSelectedWeekDate(d => {
      const next = new Date(d.getTime());
      next.setDate(next.getDate() - 7);
      return next;
    });
  }, []);

  const nextWeek = useCallback(() => {
    setSelectedWeekDate(d => {
      const next = new Date(d.getTime());
      next.setDate(next.getDate() + 7);
      return next;
    });
  }, []);

  const weekDays = useMemo(() => getDaysOfWeek(selectedWeekDate), [selectedWeekDate, getDaysOfWeek]);
  const weekStartStr = useMemo(() => `${String(weekDays[0].getDate()).padStart(2, '0')}/${String(weekDays[0].getMonth() + 1).padStart(2, '0')}`, [weekDays]);
  const weekEndStr = useMemo(() => `${String(weekDays[6].getDate()).padStart(2, '0')}/${String(weekDays[6].getMonth() + 1).padStart(2, '0')}`, [weekDays]);
  const weekYear = useMemo(() => weekDays[0].getFullYear(), [weekDays]);

  const prevMaintLogMonth = () => { if (maintLogMonth === 0) { setMaintLogYear(y => y - 1); setMaintLogMonth(11); } else setMaintLogMonth(m => m - 1); };
  const nextMaintLogMonth = () => { if (maintLogMonth === 11) { setMaintLogYear(y => y + 1); setMaintLogMonth(0); } else setMaintLogMonth(m => m + 1); };

  // ============================================================
  // PUBLIC SIGNING PAGE (detect ?firmar=RENTAL_ID)
  // ============================================================
  const signRentalId = useMemo(() => {
    const params = new URLSearchParams(window.location.search);
    return params.get('firmar');
  }, []);

  const signCanvasRef = useRef<HTMLCanvasElement>(null);
  const [signIsDrawing, setSignIsDrawing] = useState(false);
  const [signRentalData, setSignRentalData] = useState<{rental: Rental; customer: Customer; bike: Product} | null>(null);
  const [signBatteryCount, setSignBatteryCount] = useState(0);
  const [signLoading, setSignLoading] = useState(true);
  const [signSuccess, setSignSuccess] = useState(false);
  const [signSubmitting, setSignSubmitting] = useState(false);
  const [signHasSignature, setSignHasSignature] = useState(false);
  const [signImageConsent, setSignImageConsent] = useState(false);
  const [signAccepted, setSignAccepted] = useState(false);

  // Load rental data for signing page
  useEffect(() => {
    if (!signRentalId) return;
    (async () => {
      try {
        const { data: rentalRow } = await supabase.from('rentals').select('*').eq('id', signRentalId).single();
        if (!rentalRow) { setSignLoading(false); return; }
        const rental = rentalRow as Rental;
        const { data: customerRow } = await supabase.from('customers').select('*').eq('id', rental.customer_id).single();
        const { data: bikeRow } = await supabase.from('products').select('*, product_models(*)').eq('id', rental.bike_id).single();
        // Batteries handed over with this rental, for the contract details block.
        const { data: itemRows } = await supabase
          .from('rental_items').select('item_type').eq('rental_id', signRentalId);
        setSignBatteryCount((itemRows ?? []).filter(i => i.item_type === 'battery').length);
        if (customerRow && bikeRow) {
          const pm = (bikeRow as Record<string, unknown>).product_models as Record<string, unknown> | null;
          // `brand` may carry the identification colour appended as "Brand#rrggbb".
          const brand = ((pm?.brand as string) ?? '').split('#')[0].trim();
          const bikeName = pm
            ? `${brand} ${(pm?.model_name as string) ?? ''}`.trim()
            : (bikeRow as Record<string, unknown>).serial_number as string;
          setSignRentalData({
            rental,
            customer: customerRow as Customer,
            bike: { ...bikeRow as unknown as Product, name: bikeName },
          });
        }
      } catch { /* ignore */ }
      setSignLoading(false);
    })();
  }, [signRentalId]);

  // Canvas drawing helpers for signing
  const getCanvasPoint = (canvas: HTMLCanvasElement, e: React.TouchEvent | React.MouseEvent) => {
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;
    if ('touches' in e) {
      return { x: (e.touches[0].clientX - rect.left) * scaleX, y: (e.touches[0].clientY - rect.top) * scaleY };
    }
    return { x: ((e as React.MouseEvent).clientX - rect.left) * scaleX, y: ((e as React.MouseEvent).clientY - rect.top) * scaleY };
  };

  const startSign = (e: React.TouchEvent<HTMLCanvasElement> | React.MouseEvent<HTMLCanvasElement>) => {
    const canvas = signCanvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    setSignIsDrawing(true);
    const { x, y } = getCanvasPoint(canvas, e);
    ctx.beginPath();
    ctx.moveTo(x, y);
  };

  const drawSign = (e: React.TouchEvent<HTMLCanvasElement> | React.MouseEvent<HTMLCanvasElement>) => {
    if (!signIsDrawing) return;
    const canvas = signCanvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const { x, y } = getCanvasPoint(canvas, e);
    ctx.lineWidth = 2.5;
    ctx.lineCap = 'round';
    ctx.strokeStyle = '#10b981';
    ctx.lineTo(x, y);
    ctx.stroke();
    setSignHasSignature(true);
  };

  const stopSign = () => setSignIsDrawing(false);

  const clearSign = () => {
    const canvas = signCanvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    setSignHasSignature(false);
  };

  // Details the rider is signing: the frozen snapshot when one exists, otherwise
  // rebuilt from live data so links created before this feature still work.
  const signContractSnapshot = useMemo<RentalContractSnapshot | null>(() => {
    if (!signRentalData) return null;
    const stored = signRentalData.rental.contract_snapshot;
    if (stored) return stored;
    const { rental, customer, bike } = signRentalData;
    return {
      lessee_name: `${customer.first_name} ${customer.last_name}`.trim(),
      lessee_address: customer.address ?? '',
      lessee_phone: customer.phone ?? '',
      lessee_email: customer.email ?? '',
      email_lang: 'en',
      bike_brand_model: bike.name ?? '',
      bike_serial: bike.frame_serial ?? '',
      bike_ref: bike.serial_number ?? '',
      start_date: rental.start_date,
      payment_due_weekday: contractPaymentWeekday(rental.start_date),
      rate_amount: rental.rental_rate,
      rate_type: rental.rate_type,
      deposit_amount: rental.deposit_amount,
      battery_count: signBatteryCount,
    };
  }, [signRentalData, signBatteryCount]);

  const submitSignature = async () => {
    const canvas = signCanvasRef.current;
    if (!canvas || !signRentalData || !signContractSnapshot) return;
    if (!signHasSignature) {
      alert(language === 'es' ? 'Por favor firmá dentro del recuadro antes de continuar.' : 'Please sign inside the box before continuing.');
      return;
    }
    setSignSubmitting(true);
    try {
      const dataUrl = canvas.toDataURL('image/png');
      const signatureUrl = await uploadSignatureImage(signRentalData.rental.id, dataUrl);
      const signedAt = new Date().toISOString();
      await supabase.from('rentals').update({
        contract_url: signatureUrl,
        contract_signed_at: signedAt,
        contract_image_consent: signImageConsent,
        contract_snapshot: signContractSnapshot,
      }).eq('id', signRentalData.rental.id);
      sendRentalContractCopyEmail(
        signContractSnapshot,
        { signature_url: signatureUrl, signed_at: fmtDMYTime(signedAt), image_consent: signImageConsent },
        signContractSnapshot.email_lang,
      );
      setSignSuccess(true);
    } catch (err) {
      console.error('Signature upload failed:', err);
      alert('Error al guardar la firma. Inténtalo de nuevo.');
    }
    setSignSubmitting(false);
  };

  // ============================================================
  // PUBLIC DELIVERY CHECKLIST PAGE (detect ?checklist=CHECKLIST_ID)
  // ============================================================
  const checklistId = useMemo(() => {
    const params = new URLSearchParams(window.location.search);
    return params.get('checklist');
  }, []);

  const checklistCanvasRef = useRef<HTMLCanvasElement>(null);
  const [checklistIsDrawing, setChecklistIsDrawing] = useState(false);
  const [checklistHasSignature, setChecklistHasSignature] = useState(false);
  const [checklistData, setChecklistData] = useState<DeliveryChecklist | null>(null);
  const [checklistLoading, setChecklistLoading] = useState(true);
  const [checklistSuccess, setChecklistSuccess] = useState(false);
  const [checklistSubmitting, setChecklistSubmitting] = useState(false);
  const [checklistItems, setChecklistItems] = useState<Record<string, boolean>>({});
  const [checklistBattery, setChecklistBattery] = useState('');

  useEffect(() => {
    if (!checklistId) return;
    (async () => {
      try {
        const cl = await getDeliveryChecklist(checklistId);
        setChecklistData(cl);
      } catch { /* ignore */ }
      setChecklistLoading(false);
    })();
  }, [checklistId]);

  const startChecklistSign = (e: React.TouchEvent<HTMLCanvasElement> | React.MouseEvent<HTMLCanvasElement>) => {
    const canvas = checklistCanvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    setChecklistIsDrawing(true);
    setChecklistHasSignature(true);
    const { x, y } = getCanvasPoint(canvas, e);
    ctx.beginPath();
    ctx.moveTo(x, y);
  };

  const drawChecklistSign = (e: React.TouchEvent<HTMLCanvasElement> | React.MouseEvent<HTMLCanvasElement>) => {
    if (!checklistIsDrawing) return;
    const canvas = checklistCanvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const { x, y } = getCanvasPoint(canvas, e);
    ctx.lineWidth = 2.5;
    ctx.lineCap = 'round';
    ctx.strokeStyle = '#10b981';
    ctx.lineTo(x, y);
    ctx.stroke();
  };

  const stopChecklistSign = () => setChecklistIsDrawing(false);

  const clearChecklistSign = () => {
    const canvas = checklistCanvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    setChecklistHasSignature(false);
  };

  const allChecklistItemsChecked = DELIVERY_CHECKLIST_CHECKBOX_KEYS.every(k => checklistItems[k]);

  const submitChecklist = async () => {
    const canvas = checklistCanvasRef.current;
    if (!canvas || !checklistData) return;
    if (!allChecklistItemsChecked) {
      alert('Please tick every box to confirm your acceptance.');
      return;
    }
    if (!checklistHasSignature) {
      alert('Please sign before submitting.');
      return;
    }
    setChecklistSubmitting(true);
    try {
      const dataUrl = canvas.toDataURL('image/png');
      const signatureUrl = await uploadChecklistSignature(checklistData.id, dataUrl);
      const payload = { items: checklistItems, battery_level: checklistBattery, signature_url: signatureUrl };
      const ok = await submitDeliveryChecklist(checklistData.id, payload);
      if (!ok) {
        // Row was no longer 'pending' (already submitted) – do not re-send.
        setChecklistData({ ...checklistData, status: 'completed' });
        setChecklistSubmitting(false);
        return;
      }
      sendDeliveryChecklistCopyEmail(checklistData, payload, checklistData.email_lang);
      setChecklistSuccess(true);
    } catch (err) {
      console.error('Checklist submit failed:', err);
      alert('Error submitting the checklist. Please try again.');
    }
    setChecklistSubmitting(false);
  };

  // Render delivery checklist page if ?checklist= is present (no auth required).
  // The checklist document is always in English (matches the PDF model).
  if (checklistId) {
    return (
      <div className="sign-page">
        <div className="sign-page-card">
          <div className="sign-logo">
            <p style={{ fontSize: '28px', marginBottom: '4px' }}>🐏</p>
            <h2>The Fast Sheep</h2>
            <p style={{ fontSize: '12px', color: 'var(--text-muted)' }}>E-Bike Delivery Checklist</p>
            <p style={{ fontSize: '11px', color: 'var(--text-muted)' }}>Customer Acknowledgement &amp; Liability Waiver</p>
          </div>

          {checklistLoading ? (
            <div style={{ textAlign: 'center', padding: '40px' }}>
              <p style={{ color: 'var(--text-muted)' }}>⏳ Loading checklist...</p>
            </div>
          ) : !checklistData ? (
            <div style={{ textAlign: 'center', padding: '40px' }}>
              <p style={{ fontSize: '48px', marginBottom: '12px' }}>❌</p>
              <h3 style={{ marginBottom: '8px' }}>Checklist not found</h3>
              <p style={{ color: 'var(--text-muted)', fontSize: '13px' }}>This link is invalid or has expired.</p>
            </div>
          ) : checklistSuccess || checklistData.status === 'completed' ? (
            <div className="sign-success">
              <span className="check-icon">✅</span>
              <h3>Checklist submitted successfully!</h3>
              <p>Thank you, {checklistData.customer_name}. Your acceptance has been registered and a copy has been emailed to you.</p>
              <p style={{ marginTop: '12px', fontSize: '12px', color: 'var(--text-muted)' }}>This form can no longer be submitted. You can close this window.</p>
            </div>
          ) : (
            <>
              <div className="contract-details">
                {[
                  ['E-Bike Model', checklistData.bike_model || '—'],
                  ['E-Bike Serial Number', checklistData.bike_serial || '—'],
                  ['Unit Reference', checklistData.bike_ref || '—'],
                  ['Date', checklistData.delivery_date],
                  ['Customer Name', checklistData.customer_name],
                ].map(([label, val]) => (
                  <div key={label} className="detail-row">
                    <span className="detail-label">{label}</span>
                    <span className="detail-value">{val}</span>
                  </div>
                ))}
              </div>

              <div className="checklist-field">
                <label htmlFor="battery-level">🔋 Battery Charge Level</label>
                <input
                  id="battery-level"
                  type="text"
                  inputMode="numeric"
                  placeholder="e.g. 100%"
                  value={checklistBattery}
                  onChange={(e) => setChecklistBattery(e.target.value)}
                />
              </div>

              {DELIVERY_CHECKLIST_GROUPS.map(group => (
                <div key={group.key} className="checklist-group">
                  <p className="checklist-group-title">{group.title}</p>
                  {group.kind === 'checkbox'
                    ? group.items.map(item => (
                        <label key={item.key} className={`checklist-item ${checklistItems[item.key] ? 'checked' : ''}`}>
                          <input
                            type="checkbox"
                            checked={!!checklistItems[item.key]}
                            onChange={(e) => setChecklistItems(prev => ({ ...prev, [item.key]: e.target.checked }))}
                          />
                          <span>{item.text}</span>
                        </label>
                      ))
                    : group.items.map(item => (
                        <p key={item.key} className="checklist-declaration">{item.text}</p>
                      ))}
                </div>
              ))}

              <p className="checklist-signing-note">
                By signing below, the customer confirms acceptance of all the aforementioned conditions and declarations.
              </p>

              <div className="sign-canvas-container">
                <label>✍️ Sign here (use your finger or mouse):</label>
                <canvas
                  ref={checklistCanvasRef}
                  width={480}
                  height={160}
                  onMouseDown={startChecklistSign}
                  onMouseMove={drawChecklistSign}
                  onMouseUp={stopChecklistSign}
                  onMouseLeave={stopChecklistSign}
                  onTouchStart={startChecklistSign}
                  onTouchMove={drawChecklistSign}
                  onTouchEnd={stopChecklistSign}
                />
              </div>

              {!allChecklistItemsChecked && (
                <p style={{ fontSize: '12px', color: 'var(--text-muted)', textAlign: 'center', margin: '4px 0 0' }}>
                  Tick all boxes and sign to enable submission.
                </p>
              )}
              <div className="sign-actions">
                <button className="btn-secondary" style={{ flex: 1 }} onClick={clearChecklistSign}>🗑️ Clear</button>
                <button
                  className="btn-primary"
                  style={{ flex: 2 }}
                  disabled={checklistSubmitting || !allChecklistItemsChecked || !checklistHasSignature}
                  onClick={submitChecklist}
                >
                  {checklistSubmitting ? '⏳ Submitting...' : '✅ Confirm & Submit'}
                </button>
              </div>
            </>
          )}
        </div>
      </div>
    );
  }


  // ============================================================
  // PAGINA PUBLICA DEL ANEXO (?anexo=ID)
  // Reutiliza el canvas y los handlers de la firma del contrato: nunca se
  // renderizan las dos paginas a la vez.
  // ============================================================
  const amendmentId = useMemo(() => new URLSearchParams(window.location.search).get('anexo'), []);
  const [amendmentData, setAmendmentData] = useState<RentalContractAmendment | null>(null);
  const [amendmentLoading, setAmendmentLoading] = useState(true);
  const [amendmentSuccess, setAmendmentSuccess] = useState(false);
  const [amendmentSubmitting, setAmendmentSubmitting] = useState(false);

  useEffect(() => {
    if (!amendmentId) return;
    (async () => {
      try {
        setAmendmentData(await getContractAmendment(amendmentId));
      } catch (err) {
        console.error('No se pudo cargar el anexo:', err);
      }
      setAmendmentLoading(false);
    })();
  }, [amendmentId]);

  const submitAmendmentSignature = async () => {
    const canvas = signCanvasRef.current;
    if (!canvas || !amendmentData || !signHasSignature) return;
    setAmendmentSubmitting(true);
    try {
      const url = await uploadSignatureImage(`amendment-${amendmentData.id}`, canvas.toDataURL('image/png'));
      await signContractAmendment(amendmentData.id, url);
      sendAmendmentCopyEmail(amendmentData, url, fmtDMYTime(new Date()));
      setAmendmentSuccess(true);
    } catch (err) {
      console.error('No se pudo guardar la firma del anexo:', err);
      alert('Error al guardar la firma. Inténtalo de nuevo.');
    }
    setAmendmentSubmitting(false);
  };

  if (amendmentId) {
    const am = amendmentData;
    return (
      <div className="sign-page">
        <div className="sign-page-card">
          <div className="sign-logo">
            <p style={{ fontSize: '28px', marginBottom: '4px' }}>🐏</p>
            <h2>THE FAST SHEEP LIMITED</h2>
            <p style={{ fontSize: '12px', color: 'var(--text-muted)' }}>
              {am ? `Amendment No. ${am.number} to the Electric Bicycle Rental Agreement` : 'Amendment to the Rental Agreement'}
            </p>
          </div>

          {amendmentLoading ? (
            <div style={{ textAlign: 'center', padding: '40px' }}>
              <p style={{ color: 'var(--text-muted)' }}>⏳ Loading amendment...</p>
            </div>
          ) : !am ? (
            <div style={{ textAlign: 'center', padding: '40px' }}>
              <p style={{ fontSize: '48px', marginBottom: '12px' }}>❌</p>
              <h3 style={{ marginBottom: '8px' }}>Amendment not found</h3>
              <p style={{ color: 'var(--text-muted)', fontSize: '13px' }}>This link is invalid or has expired.</p>
            </div>
          ) : amendmentSuccess || am.status === 'signed' ? (
            <div className="sign-success">
              <span className="check-icon">✅</span>
              <h3>Amendment signed successfully!</h3>
              <p>Thank you, {am.customer_name}. A copy has been emailed to you.</p>
              <p style={{ marginTop: '12px', fontSize: '12px', color: 'var(--text-muted)' }}>You can close this window.</p>
            </div>
          ) : (
            <>
              <div className="terms-box">
                <p style={{ fontWeight: 700, marginTop: 0 }}>BACKGROUND</p>
                <p>
                  The parties entered into an Electric Bicycle Rental Agreement (the "Agreement"). By this
                  Amendment they agree to modify the terms listed below, with effect from <strong>{fmtDMY(am.effective_date)}</strong>.
                </p>
              </div>

              <p style={{ fontSize: '14px', fontWeight: 700, margin: '0 0 8px' }}>AMENDED TERMS</p>
              <div className="contract-details">
                {am.changes.map((c, i) => (
                  <div key={i} className="detail-row" style={{ alignItems: 'flex-start' }}>
                    <span className="detail-label">{c.label}</span>
                    <span className="detail-value" style={{ textAlign: 'right' }}>
                      <span style={{ color: 'var(--text-muted)', textDecoration: 'line-through' }}>{c.before}</span>
                      {'  →  '}
                      <strong>{c.after}</strong>
                    </span>
                  </div>
                ))}
              </div>

              <div className="terms-box">
                {am.changes.some(c => /Fee|Rate/i.test(c.label)) && <p>{AMENDMENT_RATE_CLAUSE}</p>}
                <p>{AMENDMENT_CONTINUITY_CLAUSE}</p>
              </div>

              <div className="terms-box">
                <p style={{ fontWeight: 700, marginTop: 0 }}>SIGNATURE</p>
                <p>By signing below, the LESSEE confirms that:</p>
                <ul style={{ margin: '4px 0 4px 18px', padding: 0 }}>
                  {AMENDMENT_ACKNOWLEDGEMENTS.map(a => <li key={a} style={{ marginBottom: '3px' }}>{a}</li>)}
                </ul>
              </div>

              <label style={{ display: 'flex', gap: '10px', alignItems: 'flex-start', margin: '12px 0', cursor: 'pointer', fontSize: '12px', lineHeight: 1.5 }}>
                <input type="checkbox" checked={signAccepted} onChange={e => setSignAccepted(e.target.checked)}
                  style={{ width: '18px', height: '18px', marginTop: '1px', flexShrink: 0, cursor: 'pointer' }} />
                <span><strong>I have read and accept the terms of this Amendment.</strong></span>
              </label>

              <div className="sign-canvas-container">
                <label>✍️ Sign here:</label>
                <canvas
                  ref={signCanvasRef}
                  width={480}
                  height={160}
                  onMouseDown={startSign}
                  onMouseMove={drawSign}
                  onMouseUp={stopSign}
                  onMouseLeave={stopSign}
                  onTouchStart={startSign}
                  onTouchMove={drawSign}
                  onTouchEnd={stopSign}
                />
              </div>
              <div className="sign-actions">
                <button className="btn-secondary" style={{ flex: 1 }} onClick={clearSign}>🗑️ Clear</button>
                <button className="btn-primary" style={{ flex: 2 }}
                  disabled={amendmentSubmitting || !signAccepted || !signHasSignature}
                  onClick={submitAmendmentSignature}>
                  {amendmentSubmitting ? '⏳ Saving...' : '✅ Sign & Accept'}
                </button>
              </div>
            </>
          )}
        </div>
      </div>
    );
  }

  // Render signing page if ?firmar= is present (no auth required)
  if (signRentalId) {
    return (
      <div className="sign-page">
        <div className="sign-page-card">
          <div className="sign-logo">
            <p style={{ fontSize: '28px', marginBottom: '4px' }}>🐏</p>
            <h2>The Fast Sheep</h2>
            <p style={{ fontSize: '12px', color: 'var(--text-muted)' }}>{language === 'es' ? 'Contrato Digital de Alquiler' : 'Digital Rental Contract'}</p>
          </div>

          {signLoading ? (
            <div style={{ textAlign: 'center', padding: '40px' }}>
              <p style={{ color: 'var(--text-muted)' }}>{language === 'es' ? '⏳ Cargando contrato...' : '⏳ Loading contract...'}</p>
            </div>
          ) : !signRentalData ? (
            <div style={{ textAlign: 'center', padding: '40px' }}>
              <p style={{ fontSize: '48px', marginBottom: '12px' }}>❌</p>
              <h3 style={{ marginBottom: '8px' }}>{language === 'es' ? 'Contrato no encontrado' : 'Contract not found'}</h3>
              <p style={{ color: 'var(--text-muted)', fontSize: '13px' }}>{language === 'es' ? 'Este enlace de firma no es válido o ha expirado.' : 'This signature link is invalid or has expired.'}</p>
            </div>
          ) : signSuccess ? (
            <div className="sign-success">
              <span className="check-icon">✅</span>
              <h3>{language === 'es' ? '¡Contrato firmado correctamente!' : 'Contract signed successfully!'}</h3>
              <p>{language === 'es' ? `Gracias, ${signRentalData.customer.first_name}. Tu firma ha sido registrada exitosamente.` : `Thank you, ${signRentalData.customer.first_name}. Your signature has been registered successfully.`}</p>
              <p style={{ marginTop: '12px', fontSize: '12px', color: 'var(--text-muted)' }}>{language === 'es' ? 'Puedes cerrar esta ventana.' : 'You can close this window.'}</p>
            </div>
          ) : (
            <>
              {/* RENTAL DETAILS — pre-filled from the wizard */}
              <h3 style={{ fontSize: '14px', margin: '0 0 8px', letterSpacing: '0.04em' }}>RENTAL DETAILS</h3>
              <div className="contract-details">
                {contractDetailRows(signContractSnapshot!).map(([label, val]) => (
                  <div key={label} className="detail-row">
                    <span className="detail-label">{label}</span>
                    <span className="detail-value">{val}</span>
                  </div>
                ))}
              </div>

              {/* Full agreement. English only: it reproduces the signed PDF. */}
              <div className="terms-box" style={{ maxHeight: '380px', overflowY: 'auto' }}>
                <p style={{ fontWeight: 700, marginTop: 0 }}>ELECTRIC BICYCLE RENTAL AGREEMENT</p>
                <p>{RENTAL_CONTRACT_INTRO}</p>
                {RENTAL_CONTRACT_CLAUSES.map(clause => (
                  <div key={clause.title}>
                    <p style={{ fontWeight: 700, marginBottom: '2px' }}>{clause.title}</p>
                    {(clause.paragraphs ?? []).map((p, i) => <p key={`p${i}`}>{p}</p>)}
                    {(clause.bullets ?? []).length > 0 && (
                      <ul style={{ margin: '4px 0 4px 18px', padding: 0 }}>
                        {(clause.bullets ?? []).map((b, i) => <li key={`b${i}`} style={{ marginBottom: '3px' }}>{b}</li>)}
                      </ul>
                    )}
                    {(clause.closing ?? []).map((p, i) => <p key={`c${i}`}>{p}</p>)}
                  </div>
                ))}
              </div>

              {/* SIGNATURES */}
              <div className="terms-box">
                <p style={{ fontWeight: 700, marginTop: 0 }}>SIGNATURES</p>
                <p>By signing below, the LESSEE confirms that:</p>
                <ul style={{ margin: '4px 0 4px 18px', padding: 0 }}>
                  {CONTRACT_SIGNATURE_ACKNOWLEDGEMENTS.map(a => <li key={a} style={{ marginBottom: '3px' }}>{a}</li>)}
                </ul>
              </div>

              {/* Clause 13 consent — optional and independent from accepting the agreement */}
              <label style={{ display: 'flex', gap: '10px', alignItems: 'flex-start', margin: '12px 0', cursor: 'pointer', fontSize: '12px', lineHeight: 1.5 }}>
                <input
                  type="checkbox"
                  checked={signImageConsent}
                  onChange={e => setSignImageConsent(e.target.checked)}
                  style={{ width: '18px', height: '18px', marginTop: '1px', flexShrink: 0, cursor: 'pointer' }}
                />
                <span>{CONTRACT_IMAGE_CONSENT_TEXT}</span>
              </label>

              {/* Required acceptance */}
              <label style={{ display: 'flex', gap: '10px', alignItems: 'flex-start', margin: '12px 0', cursor: 'pointer', fontSize: '12px', lineHeight: 1.5 }}>
                <input
                  type="checkbox"
                  checked={signAccepted}
                  onChange={e => setSignAccepted(e.target.checked)}
                  style={{ width: '18px', height: '18px', marginTop: '1px', flexShrink: 0, cursor: 'pointer' }}
                />
                <span><strong>I have read and accept the terms and conditions of this Agreement.</strong></span>
              </label>

              <div className="sign-canvas-container">
                <label>{language === 'es' ? '✍️ Firma aquí (use su dedo o ratón):' : '✍️ Sign here (use your finger or mouse):'}</label>
                <canvas
                  ref={signCanvasRef}
                  width={480}
                  height={160}
                  onMouseDown={startSign}
                  onMouseMove={drawSign}
                  onMouseUp={stopSign}
                  onMouseLeave={stopSign}
                  onTouchStart={startSign}
                  onTouchMove={drawSign}
                  onTouchEnd={stopSign}
                />
              </div>
              <div className="sign-actions">
                <button className="btn-secondary" style={{ flex: 1 }} onClick={clearSign}>🗑️ {language === 'es' ? 'Limpiar' : 'Clear'}</button>
                <button
                  className="btn-primary"
                  style={{ flex: 2 }}
                  disabled={signSubmitting || !signAccepted || !signHasSignature}
                  onClick={submitSignature}
                >
                  {signSubmitting ? (language === 'es' ? '⏳ Guardando...' : '⏳ Saving...') : (language === 'es' ? '✅ Firmar y Aceptar' : '✅ Sign & Accept')}
                </button>
              </div>
              {(!signAccepted || !signHasSignature) && (
                <p style={{ fontSize: '11px', color: 'var(--text-muted)', textAlign: 'center', marginTop: '8px' }}>
                  {language === 'es'
                    ? 'Marcá la aceptación y firmá en el recuadro para continuar.'
                    : 'Tick the acceptance box and sign in the box to continue.'}
                </p>
              )}
            </>
          )}
        </div>
      </div>
    );
  }

  // ============================================================
  // LOADING SCREEN
  // ============================================================
  // ============================================================
  // AUTH LOADING
  // ============================================================
  if (authLoading) return (
    <div className="loading-screen">
      <div className="loading-spinner-ring" />
      <h2>The Fast Sheep</h2>
      <p>{language === 'es' ? 'Verificando sesión...' : 'Verifying session...'}</p>
    </div>
  );

  // ============================================================
  // LOGIN SCREEN (not authenticated)
  // ============================================================
  if (!session) return (
    <div className="login-screen">
      <div className="login-card">
        <div className="login-logo" style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '8px' }}>
          <img src="/logo.png" alt="The Fast Sheep Logo" style={{ height: '64px', width: 'auto', borderRadius: '12px', objectFit: 'contain', marginBottom: '8px' }} />
          <h1 style={{ marginTop: '0' }}>The Fast Sheep</h1>
          <p className="login-subtitle">Fleet Master · Dublin ERP</p>
        </div>
        <p className="login-desc">
          {language === 'es'
            ? 'Gestión inteligente de flota de e-bikes para delivery en Dublín.'
            : 'Smart e-bike fleet management for Dublin delivery riders.'}
        </p>

        {authError && (
          <div style={{
            background: 'rgba(239, 68, 68, 0.1)',
            border: '1px solid rgba(239, 68, 68, 0.2)',
            borderRadius: '8px',
            padding: '12px',
            marginBottom: '16px',
            color: '#f87171',
            fontSize: '13px',
            textAlign: 'center',
            display: 'flex',
            flexDirection: 'column',
            gap: '6px',
            alignItems: 'center'
          }}>
            <span style={{ fontSize: '18px' }}>⚠️</span>
            <span>{authError}</span>
            <button 
              onClick={() => setAuthError(null)} 
              style={{
                background: 'none',
                border: 'none',
                color: '#9ca3af',
                cursor: 'pointer',
                fontSize: '11px',
                textDecoration: 'underline',
                padding: '2px 8px'
              }}
            >
              {language === 'es' ? 'Descartar' : 'Dismiss'}
            </button>
          </div>
        )}

        <button className="btn-google" onClick={signInWithGoogle}>

          <svg className="google-icon" viewBox="0 0 24 24" width="20" height="20">
            <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92a5.06 5.06 0 0 1-2.2 3.32v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.1z" fill="#4285F4"/>
            <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853"/>
            <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" fill="#FBBC05"/>
            <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335"/>
          </svg>
          {language === 'es' ? 'Iniciar sesión con Google' : 'Sign in with Google'}
        </button>
        <div className="login-lang">
          <button className={language === 'es' ? 'active' : ''} onClick={() => setLanguage('es')}>🇪🇸 Español</button>
          <button className={language === 'en' ? 'active' : ''} onClick={() => setLanguage('en')}>🇬🇧 English</button>
        </div>
        <p className="login-footer">Powered by Supabase · Dublin, Ireland</p>
      </div>
    </div>
  );

  // ============================================================
  // DATA LOADING
  // ============================================================
  if (loading) return (
    <div className="loading-screen">
      <div className="loading-spinner-ring" />
      <img src="/logo.png" alt="The Fast Sheep Logo" style={{ height: '48px', width: 'auto', borderRadius: '8px', objectFit: 'contain', marginTop: '16px' }} />
      <h2 style={{ marginTop: '12px' }}>The Fast Sheep</h2>
      <p>{language === 'es' ? 'Conectando a Supabase...' : 'Connecting to Supabase...'}</p>
    </div>
  );

  // ============================================================
  // ERROR SCREEN
  // ============================================================
  if (connectionError) return (
    <div className="error-screen">
      <div className="error-icon">🔴</div>
      <h2>{language === 'es' ? 'Error de Conexión con Supabase' : 'Supabase Connection Error'}</h2>
      <p className="error-detail">{connectionError}</p>
      <p style={{ fontSize: '13px', color: 'var(--text-muted)', marginTop: '8px' }}>
        {language === 'es' ? 'Verifica que tu archivo .env tiene las variables VITE_SUPABASE_URL y VITE_SUPABASE_ANON_KEY correctas.' : 'Verify that your .env file has the correct VITE_SUPABASE_URL and VITE_SUPABASE_ANON_KEY variables.'}
      </p>
      <button className="btn-primary" style={{ marginTop: '24px' }} onClick={() => triggerReload()}>
        🔄 {language === 'es' ? 'Reintentar Conexión' : 'Retry Connection'}
      </button>
    </div>
  );

  // ============================================================
  // TASK BOARD ACTIONS (WITH LOCAL FALLBACK)
  // ============================================================
  const handleSaveCard = async (title: string, existingId?: string) => {
    const cardId = existingId || crypto.randomUUID();
    const newCard: TaskCard = {
      id: cardId,
      title,
      created_at: new Date().toISOString()
    };
    
    // Optimistic / Local update first
    let updatedCards = [...taskCards];
    if (existingId) {
      updatedCards = updatedCards.map(c => c.id === existingId ? { ...c, title } : c);
    } else {
      updatedCards.push(newCard);
    }
    setTaskCards(updatedCards);

    try {
      await upsertTaskCard(newCard);
    } catch (err) {
      console.warn('[FastSheep] Error saving card to Supabase. Saving to localStorage.', err);
      localStorage.setItem('fast_sheep_task_cards', JSON.stringify(updatedCards));
    }
  };

  const handleDeleteCard = async (id: string) => {
    const updatedCards = taskCards.filter(c => c.id !== id);
    const updatedItems = taskItems.filter(item => item.card_id !== id);
    setTaskCards(updatedCards);
    setTaskItems(updatedItems);

    try {
      await deleteTaskCard(id);
    } catch (err) {
      console.warn('[FastSheep] Error deleting card from Supabase. Saving to localStorage.', err);
      localStorage.setItem('fast_sheep_task_cards', JSON.stringify(updatedCards));
      localStorage.setItem('fast_sheep_task_items', JSON.stringify(updatedItems));
    }
  };

  const handleSaveTask = async (item: Partial<TaskItem>) => {
    const itemId = item.id || crypto.randomUUID();
    const existing = taskItems.find(t => t.id === itemId);
    const text = item.text !== undefined ? item.text : (existing?.text || '');
    const completed = item.completed !== undefined ? item.completed : (existing?.completed || false);
    const color = item.color !== undefined ? item.color : (existing?.color || '#3b82f6');
    const card_id = item.card_id !== undefined ? item.card_id : (existing?.card_id || '');
    
    // Find next position if it's a new task
    let position = item.position !== undefined ? item.position : (existing?.position || 0);
    if (!existing) {
      const cardTasks = taskItems.filter(t => t.card_id === card_id);
      position = cardTasks.length > 0 ? Math.max(...cardTasks.map(t => t.position)) + 1 : 0;
    }

    const newTask: TaskItem = {
      id: itemId,
      card_id,
      text,
      completed,
      color,
      position,
      created_at: existing?.created_at || new Date().toISOString()
    };

    let updatedItems = [...taskItems];
    if (existing) {
      updatedItems = updatedItems.map(t => t.id === itemId ? newTask : t);
    } else {
      updatedItems.push(newTask);
    }
    // Keep it sorted
    updatedItems.sort((a, b) => a.position - b.position);
    setTaskItems(updatedItems);

    try {
      await upsertTaskItem(newTask);
    } catch (err) {
      console.warn('[FastSheep] Error saving task to Supabase. Saving to localStorage.', err);
      localStorage.setItem('fast_sheep_task_items', JSON.stringify(updatedItems));
    }
  };

  const handleDeleteTask = async (id: string) => {
    const updatedItems = taskItems.filter(t => t.id !== id);
    setTaskItems(updatedItems);

    try {
      await deleteTaskItem(id);
    } catch (err) {
      console.warn('[FastSheep] Error deleting task from Supabase. Saving to localStorage.', err);
      localStorage.setItem('fast_sheep_task_items', JSON.stringify(updatedItems));
    }
  };

  const handleSaveColorTag = async (color: string, label: string) => {
    const updatedTags = { ...colorTags, [color]: label };
    setColorTags(updatedTags);

    try {
      await upsertColorTag({ color, label });
    } catch (err) {
      console.warn('[FastSheep] Error saving color tag to Supabase. Saving to localStorage.', err);
      localStorage.setItem('fast_sheep_task_color_tags', JSON.stringify(updatedTags));
    }
  };

  const handleDeleteColorTag = async (color: string) => {
    const updatedTags = { ...colorTags };
    delete updatedTags[color];
    setColorTags(updatedTags);

    try {
      await deleteColorTag(color);
    } catch (err) {
      console.warn('[FastSheep] Error deleting color tag from Supabase. Saving to localStorage.', err);
      localStorage.setItem('fast_sheep_task_color_tags', JSON.stringify(updatedTags));
    }
  };

  const handleMoveTask = async (item: TaskItem, direction: 'up' | 'down') => {
    const cardTasks = taskItems.filter(t => t.card_id === item.card_id).sort((a, b) => a.position - b.position);
    const index = cardTasks.findIndex(t => t.id === item.id);
    if (index === -1) return;

    if (direction === 'up' && index > 0) {
      const prevItem = cardTasks[index - 1];
      const tempPos = item.position;
      item.position = prevItem.position;
      prevItem.position = tempPos;
    } else if (direction === 'down' && index < cardTasks.length - 1) {
      const nextItem = cardTasks[index + 1];
      const tempPos = item.position;
      item.position = nextItem.position;
      nextItem.position = tempPos;
    } else {
      return; // Can't move further
    }

    // Update state
    const updatedItems = taskItems.map(t => {
      const match = cardTasks.find(ct => ct.id === t.id);
      return match ? { ...t, position: match.position } : t;
    }).sort((a, b) => a.position - b.position);

    setTaskItems(updatedItems);

    try {
      // Save both updated items to Supabase
      const affected = cardTasks.slice(Math.max(0, index - 1), index + 2);
      for (const t of affected) {
        await upsertTaskItem(t);
      }
    } catch (err) {
      console.warn('[FastSheep] Error moving tasks on Supabase. Saving to localStorage.', err);
      localStorage.setItem('fast_sheep_task_items', JSON.stringify(updatedItems));
    }
  };

